import { initArt, art, buildHeroSprites, drawPreview, makePortrait, getMonsterFrame, NPC_LOOKS, weaponIcon, armorIcon, consumableIcon } from './art/index.js';
import { LOW_ABILITIES } from './data/abilities/low.js';
import { MID_ABILITIES } from './data/abilities/mid.js';
import { RARITIES, AWAKENING_WEIGHTS, rarityOf } from './data/rarity.js';
import { clamp, dist, weightedPick, rand, randInt, pick } from './utils.js';

const $ = (s) => document.querySelector(s);
const $$ = (s) => [...document.querySelectorAll(s)];
const canvas = $('#game'), ctx = canvas.getContext('2d');
ctx.imageSmoothingEnabled = false;
const W = canvas.width, H = canvas.height;
const abilities = [...LOW_ABILITIES, ...MID_ABILITIES];
const heroLook = { hair: 0, hairColor: '#2b2533', cloakColor: '#25324d' };
const state = {
  mode: 'title', name: 'Wanderer', path: 'sword', ability: null, level: 1, xp: 0, xpNext: 100,
  hp: 100, maxHp: 100, mp: 60, maxMp: 60, stamina: 100, gold: 35, kills: 0,
  time: 0.78, zone: 'HOLLOWMERE', weather: 'ASHFALL', seed: randInt(1, 999999),
  player: { x: 320, y: 240, dir: 0, frame: 0, attack: 0, invuln: 0, dodge: 0 },
  enemies: [], particles: [], projectiles: [], loot: [], zones: [], cooldowns: [0,0,0], buffs: {},
  quest: 0, dungeon: false, bossDefeated: false, inventory: [], equipment: { weapon: null, armor: null },
  settings: { sound: true, particles: true },
};
let heroSprites, last = performance.now(), elapsed = 0, dialogueIndex = 0, touchMove = { x: 0, y: 0 }, pointer = { x: W/2, y: H/2 }, activeTab = 'status', shake = 0;
const SAVE_KEY = 'eclipse-last-awakened-v1';

function hideScreens() { $$('.screen').forEach((el) => el.classList.add('hidden')); }
function showToast(message, color = '#5ed8ff') {
  const node = document.createElement('div'); node.className = 'toast'; node.style.setProperty('--toast-color', color); node.textContent = message;
  $('#toast-layer').append(node); setTimeout(() => node.remove(), 2600);
}
function showMode(mode) { state.mode = mode; }
function drawCharacter(canvasEl, w, h, frame = 0) {
  if (!heroSprites) return;
  const g = canvasEl.getContext('2d'); g.clearRect(0,0,w,h); g.imageSmoothingEnabled = false;
  const image = heroSprites.down[frame % heroSprites.down.length];
  const scale = Math.min(w / image.width, h / image.height) * 1.65;
  g.drawImage(image, (w-image.width*scale)/2, h-image.height*scale, image.width*scale, image.height*scale);
}
function refreshHero() { heroSprites = buildHeroSprites(heroLook); }
function updateCreationPreview() {
  const name = ($('#char-name').value.trim() || 'UNNAMED').toUpperCase();
  $('#preview-name').textContent = name;
  $('#preview-path').textContent = ({sword:'PATH OF THE BLADE',bow:'PATH OF THE HUNTER',staff:'PATH OF THE ARCANIST'})[state.path];
  drawPreview($('#preview-canvas'), heroLook, elapsed);
}

// Ability pool includes distinct upper-tier authorities with the same upgrade contract.
const ascendant = [
  { id:'phoenix', name:'Phoenix Rebirth', rarity:'legendary', color:'#ffb45c', sigil:'♨', tagline:'The end of a life is only a kind of kindling.', desc:'A sovereign ember lives beneath your heart. It remembers every shape you have ever burned away.', passive:{text:'+18% Max HP. Revive once per expedition with 35% HP; fire damage restores a little health.',mods:{hpPct:.18,atkPct:.14,regen:1.2}}, evolution:[{level:5,name:'Ashen Crown',desc:'Rebirth restores 55% HP and leaves a healing ember.',mods:{healPct:.2}},{level:10,name:'Dawn Unending',desc:'A rebirth erupts in a wide flame nova.',mods:{radiusPct:.25,atkPct:.12}}], skills:[
    {name:'Kindle',desc:'Send a seeking phoenix spark into nearby foes.',kind:'projectile',mana:15,cd:3.2,dmg:2.8,speed:360,radius:12,pierce:2,color:'#ff9d4d'},
    {name:'Ashen Wings',desc:'Dash through enemies and leave a burning trail.',kind:'dash',mana:20,cd:7,dmg:2.5,distance:180,radius:42,color:'#ff704d'},
    {name:'Solar Rebirth',desc:'Release the ember within: heal and scorch all nearby enemies.',kind:'nova',mana:30,cd:18,dmg:4.2,radius:135,healPct:.25,color:'#ffd16a'}]},
  { id:'void', name:'Crown of the Void', rarity:'mythic', color:'#df83ff', sigil:'◉', tagline:'There was a silence before the first star. It knows your name.', desc:'A fragment of the first darkness has chosen you as its vessel. Even distance and fear bend around its hunger.', passive:{text:'+22% Attack, +12% Dodge. Defeating an enemy briefly empowers your next skill.',mods:{atkPct:.22,dodge:.12,cdr:.08}}, evolution:[{level:5,name:'Starless Gate',desc:'Void skills gain +20% radius and pull.',mods:{radiusPct:.2}},{level:10,name:'First Silence',desc:'Every third skill casts a free echo at reduced power.',mods:{echo:true,atkPct:.15}}], skills:[
    {name:'Null Lance',desc:'Pierce the veil with a bolt that passes through a line of enemies.',kind:'projectile',mana:20,cd:3.8,dmg:3.5,speed:480,radius:13,pierce:6,color:'#dd91ff'},
    {name:'Eventide',desc:'Fold into the void, reappearing in a blast of dark matter.',kind:'teleport',mana:24,cd:8,dmg:3.4,range:210,radius:58,color:'#9e66ff'},
    {name:'World Without Stars',desc:'Create a miniature eclipse that devours everything nearby.',kind:'slam',mana:38,cd:20,dmg:5.8,radius:150,delay:.65,stun:1.2,color:'#ebadff'}]},
  { id:'seraph', name:'Seraphic Authority', rarity:'divine', color:'#fff0a0', sigil:'✧', tagline:'The light did not choose the worthy. It chose you.', desc:'Something older than worship has opened its eyes inside you. The world shines with the fragile beauty of things that can end.', passive:{text:'+25% Attack and Defense. Regenerate 2 HP and 1 MP each second.',mods:{atkPct:.25,defPct:.25,regen:2,manaRegen:1}}, evolution:[{level:5,name:'Sixfold Halo',desc:'Critical strikes release a small radiant burst.',mods:{crit:.1,radiusPct:.1}},{level:10,name:'First Light',desc:'All skills deal +25% damage and your aura heals you.',mods:{atkPct:.25,regen:2}}], skills:[
    {name:'Judgment',desc:'A ray of dawn tears through every foe in your path.',kind:'beam',mana:24,cd:5,dmg:4.1,range:360,width:38,pierce:9,color:'#fff5bd'},
    {name:'Wings of Mercy',desc:'Become briefly untouchable, healing as you rush forward.',kind:'dash',mana:22,cd:8,dmg:3,distance:200,radius:56,healPct:.1,color:'#fff0a0'},
    {name:'Heavenfall',desc:'Call a column of light onto the marked ground.',kind:'slam',mana:42,cd:22,dmg:7,radius:155,delay:.75,stun:1.5,color:'#fff6ce'}]},
];
function rollAbility() {
  const rarity = weightedPick(AWAKENING_WEIGHTS).value;
  const pool = [...abilities, ...ascendant].filter((a) => a.rarity === rarity);
  return pick(pool.length ? pool : ascendant.filter((a) => a.rarity === rarity));
}
function beginCharacter() {
  state.name = ($('#char-name').value.trim().slice(0,16) || 'Wanderer');
  state.player.x = 320; state.player.y = 236; state.player.dir = 0;
  state.hp = state.maxHp = 100; state.mp = state.maxMp = 60; state.stamina = 100;
  state.level = 1; state.xp = 0; state.gold = 35; state.kills = 0; state.quest = 0; state.dungeon = false; state.bossDefeated = false;
  state.ability = rollAbility(); state.enemies = []; state.inventory = []; state.equipment = {weapon:null,armor:null};
  hideScreens(); $('#hud').classList.remove('hidden'); $('#touch-controls').classList.remove('hidden');
  $('#awakening-screen').classList.remove('hidden'); $('#awaken-name').textContent = state.name;
  populateAwakening(); updateHud(); saveGame();
}
function populateAwakening() {
  const a = state.ability, r = rarityOf(a.rarity);
  $('#reveal-rarity').textContent = r.name.toUpperCase(); $('#reveal-rarity').style.color = r.color;
  $('#reveal-sigil').textContent = a.sigil; $('#reveal-sigil').style.color = a.color;
  $('#reveal-name').textContent = a.name; $('#reveal-name').style.color = r.color; $('#reveal-desc').textContent = a.desc;
  $('#reveal-passive').innerHTML = `<b>INNATE PASSIVE</b><span>${a.passive.text}</span>`;
  $('#reveal-stats').innerHTML = `<span>ATTACK <b>+${Math.round((a.passive.mods.atkPct||0)*100)}%</b></span><span>DEFENSE <b>+${Math.round((a.passive.mods.defPct||0)*100)}%</b></span><span>EVOLUTION <b>LV 5 / 10</b></span>`;
  $('#reveal-skills').innerHTML = a.skills.map((s,i)=>`<div><kbd>${['Q','E','R'][i]}</kbd><b>${s.name}</b><small>${s.desc}</small></div>`).join('');
  $('#ability-reveal').style.setProperty('--rarity-color', r.color);
}

const lines = [
  ['Elder Orin', 'The sky has been gone for seven years. Tonight, the old stones are answering again.'],
  ['Elder Orin', 'You came back from the northern road alive. That is more than most can say. The System chose you.'],
  ['Elder Orin', 'When the bells ring, the village sleeps behind its ward. Find the rift beyond the eastern watchtower. Do not go alone.'],
];
function openDialogue() {
  dialogueIndex = 0; $('#dialogue-layer').classList.remove('hidden'); $('#dialogue-choices').innerHTML = '';
  if (art.npcPortraits.elder) $('#dialogue-portrait').getContext('2d').drawImage(art.npcPortraits.elder,0,0,64,72);
  renderDialogue();
}
function renderDialogue() {
  const [speaker,text] = lines[Math.min(dialogueIndex,lines.length-1)];
  $('#dialogue-speaker').textContent = speaker; $('#dialogue-text').textContent = text;
  $('#dialogue-choices').innerHTML = dialogueIndex >= lines.length-1 ? '<button data-choice="rift">I will find the rift. <span>→</span></button><button data-choice="later">I need a moment.</button>' : '';
}
function closeDialogue(choice) {
  $('#dialogue-layer').classList.add('hidden');
  if (choice === 'rift') { state.quest = 1; showToast('QUEST UPDATED · The Shattered Threshold'); setQuest('The Shattered Threshold','Travel east and enter the rift.'); saveGame(); }
  if (choice === 'later') showToast('Orin waits by the old well.');
}
function setQuest(name, objective) { $('#quest-name').textContent = name; $('#quest-objective').textContent = objective; }
function acceptAwakening() {
  $('#awakening-screen').classList.add('hidden'); state.mode='world';
  setQuest('A System Awakens','Speak with Elder Orin in Hollowmere.');
  showToast(`${rarityOf(state.ability.rarity).name.toUpperCase()} AUTHORITY ACQUIRED`, rarityOf(state.ability.rarity).color);
  spawnAmbientEnemies(); saveGame();
}
function spawnAmbientEnemies() {
  const types = Object.keys(art.monsters || {});
  for (let i=0;i<5;i++) spawnEnemy(pick(types), rand(70,570), rand(90,310), false);
}
function spawnEnemy(type,x,y,boss=false) {
  state.enemies.push({type,x,y,hp:boss?240:30+state.level*7,maxHp:boss?240:30+state.level*7,speed:boss?30:rand(22,34),damage:boss?18:8+state.level,attackCd:rand(.4,1.8),frame:0,hit:0,boss,stun:0,slow:0});
}

function updateHud() {
  const pct=(n,m)=>`${clamp(n/m*100,0,100)}%`;
  $('#hud-name').textContent=state.name; $('#hud-title').textContent=state.ability?`${rarityOf(state.ability.rarity).name} Awakened`:'Unawakened';
  $('#hud-level').textContent=state.level; $('#bar-hp').style.width=pct(state.hp,state.maxHp); $('#txt-hp').textContent=`${Math.ceil(state.hp)} / ${state.maxHp}`;
  $('#bar-mp').style.width=pct(state.mp,state.maxMp); $('#txt-mp').textContent=`${Math.ceil(state.mp)} / ${state.maxMp}`;
  $('#bar-sp').style.width=`${state.stamina}%`; $('#txt-sp').textContent=Math.ceil(state.stamina);
  $('#bar-xp').style.width=pct(state.xp,state.xpNext); $('#txt-xp').textContent=`${state.xp} / ${state.xpNext} XP`;
