function dodge(){if(!player||paused||player.stamina<24)return;const dx=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0),dy=(keys.s||keys.arrowdown?1:0)-(keys.w||keys.arrowup?1:0),a=dx||dy?Math.atan2(dy,dx):player.dir;player.x=clamp(player.x+Math.cos(a)*92,18,mapW*TS-18);player.y=clamp(player.y+Math.sin(a)*92,18,mapH*TS-18);player.stamina-=24;player.invuln=.45;effects.push({x:player.x,y:player.y,radius:34,life:.4,max:.4,color:'#c4dfff'})}
function nearestProp(){return props.filter(p=>p.npc).sort((a,b)=>dist(player.x,player.y,a.x,a.y)-dist(player.x,player.y,b.x,b.y)).find(p=>dist(player.x,player.y,p.x,p.y)<62)||null}
