function update(dt){time+=dt;if(!player)return;player.playTime=(player.playTime||0)+dt;camera.x+=(player.x-camera.x)*Math.min(1,dt*7);camera.y+=(player.y-camera.y)*Math.min(1,dt*7);const dx=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0)+(touchMove.x||0),dy=(keys.s||keys.arrowdown?1:0)-(keys.w||keys.arrowup?1:0)+(touchMove.y||0),len=Math.hypot(dx,dy)||1,movespeed=145*(1+(player.mods.movePct||0));if(Math.abs(dx)+Math.abs(dy)>.05){player.x=clamp(player.x+dx/len*movespeed*dt,16,mapW*TS-16);player.y=clamp(player.y+dy/len*movespeed*dt,16,mapH*TS-16);player.anim+=dt*8;player.dir=Math.atan2(dy,dx)}else player.anim+=dt*1.5;player.attack=Math.max(0,player.attack-dt);player.invuln=Math.max(0,player.invuln-dt);player.stamina=Math.min(100,player.stamina+22*dt);player.mp=Math.min(player.maxMp,player.mp*((1)+0)+((player.mods.manaRegen||.6)*dt));player.hp=Math.min(player.maxHp,player.hp+(player.mods.regen||0)*dt);player.cd=player.cd.map(c=>Math.max(0,c-dt));player.buffs=player.buffs.filter(b=>{b.time-=dt;if(b.time<=0&&b.revert)for(const[k,v]of Object.entries(b.mods||{}))player.mods[k]=(player.mods[k]||0)-v;return b.time>0});for(const m of monsters){if(m.hp<=0)continue;m.stun=Math.max(0,m.stun-dt);m.slow=Math.max(0,m.slow-dt);m.burn=Math.max(0,m.burn-dt);m.marked=Math.max(0,(m.marked||0)-dt);m.attackCd-=dt;if(m.burn>0&&Math.random()<dt*2)damageMonster(m,Math.max(1,player.atk*(player.mods.burn||.12)*.15),{color:'#ff864b'});const d=dist(player.x,player.y,m.x,m.y);if(d<330||m.aggro){m.aggro=true;if(d>m.radius+20&&m.stun<=0){const a=Math.atan2(player.y-m.y,player.x-m.x),sp=m.speed*(m.slow>0?.48:1);m.x+=Math.cos(a)*sp*dt;m.y+=Math.sin(a)*sp*dt;m.dir=a}if(d<m.radius+25&&m.attackCd<=0&&player.invuln<=0){let dmg=m.atk*(1-(player.mods.defPct||0));if(player.shield>0){const absorbed=Math.min(player.shield,dmg);player.shield-=absorbed;dmg-=absorbed}player.hp-=dmg;player.invuln=.55;m.attackCd=m.boss?1.3:1.55;effects.push({x:player.x,y:player.y,radius:25,life:.35,max:.35,color:'#ff5d7