export function setLanguage(next) { language = next === 'en' ? 'en' : 'id'; localStorage.setItem(LANGUAGE_KEY, language); document.documentElement.lang = language; }
export function t(value) {
  if (language === 'en' || value == null) return value;
  const text = String(value);
  if (id[text] !== undefined) return id[text];
  if (words[text] !== undefined) return words[text];
  return text.replace(/\b(Common|Uncommon|Rare|Epic|Legendary|Mythic|Divine)\b/g, m => words[m] || m);
}
