27: export function t(value) {
28:   if (language === 'en' || value == null) return value;
29:   const text = String(value);
30:   if (id[text] !== undefined) return id[text];
31:   if (words[text] !== undefined) return words[text];
32:   let match = text.match(/^Reliquary Depth (\d+)$/);
33:   if (match) return `Kedalaman Relikui ${match[1]}`;
34:   match = text.match(/^Defeat (\d+) creatures and find the return gate\.$/);
35:   if (match) return `Kalahkan ${match[1]} monster dan temukan gerbang pulang.`;
36:   match = text.match(/^Entered (.+)$/);
37:   if (match) return `Memasuki ${t(match[1])}`;
38:   match = text.match(/^(.+) equipped$/);
39:   if (match) return `${t(match[1])} dipakai`;
40:   match = text.match(/^LEVEL UP · (\d+)$/);
41:   if (match) return `NAIK TINGKAT · ${match[1]}`;
42:   match = text.match(/^EVOLUTION · (.+)$/);
43:   if (match) return `EVOLUSI · ${t(match[1])}`;
44:   if (text.startsWith('DAY ')) return `HARI ${text.slice(4)}`;
45:   return text.replace(/\b(Common|Uncommon|Rare|Epic|Legendary|Mythic|Divine)\b/g, m => words[m] || m);
